def transform(grid):
    h, w = len(grid), len(grid[0])
    # The non-background marker shape is the rare color, distinct from the
    # repeated field color. Stamp that shape wherever its cells are all 0.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    color = min((c for c in counts if c != 0), key=lambda c: counts[c])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    minr, minc = min(r for r, c in pts), min(c for r, c in pts)
    shape = {(r-minr, c-minc) for r, c in pts}
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for dr in range(h-sh+1):
        for dc in range(w-sw+1):
            if all(grid[dr+r][dc+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr+r][dc+c] = color
    return out

